(() => {const root=document.documentElement;const saved=localStorage.getItem('mutan-ux-theme');if(saved)root.dataset.theme=saved;document.querySelectorAll('[data-theme-toggle]').forEach(b=>b.addEventListener('click',()=>{root.dataset.theme=root.dataset.theme==='dark'?'light':'dark';localStorage.setItem('mutan-ux-theme',root.dataset.theme)}));const toast=(msg='已保存原型状态')=>{let e=document.querySelector('.toast');if(!e){e=document.createElement('div');e.className='toast';document.body.append(e)}e.textContent=msg;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),1800)};document.querySelectorAll('[data-toast]').forEach(b=>b.addEventListener('click',()=>toast(b.dataset.toast)));document.querySelectorAll('[data-like]').forEach(b=>b.addEventListener('click',()=>{b.classList.toggle('liked');const n=b.querySelector('span');if(n)n.textContent=Number(n.textContent)+(b.classList.contains('liked')?1:-1)}));document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{b.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('active'));b.classList.add('active');toast('已切换至「'+b.textContent.trim()+'」视图')}));})();
